  lat: "46.9753710",
  lon: "-123.8157220",
  address: {
    town: "Aberdeen",
    county: "Grays Harbor County",
    state: "Washington",
    country: "United States",
  },
};

const okJson = (data) => ({ ok: true, json: () => Promise.resolve(data) });

