51	/**
52	 * Takes the lock, returning an opaque token on success and `null` when it is
53	 * already held.
54	 *
55	 * The token is what makes the lock safe to *modify* after the fact (see
56	 * `releaseThrottleAfter`). A lock whose value is a constant can only be taken
57	 * and waited out: any holder trying to shorten or extend it is really saying
58	 * "change whatever lock is there now", which silently mangles a *different*
59	 * holder's lock if the original lease lapsed mid-request.
60	 */
61	export async function acquireThrottle(redis, service, minIntervalMs) {
62	  const token = globalThis.crypto.randomUUID();
63	  const result = await redis.set(`throttle:${service}`, token, {
64	    nx: true,
65	    px: minIntervalMs,
66	  });
67	  return result !== null ? token : null;
68	}
69	
70	// Compare-and-shorten, the fenced counterpart to acquireThrottle. Both
71	// branches first check that the lock still carries our token, so a lease that
72	// expired mid-request leaves someone else's lock untouched.
73	const SHORTEN_IF_OURS = `
74	if redis.call("get", KEYS[1]) ~= ARGV[1] then return 0 end
75	if tonumber(ARGV[2]) <= 0 then return redis.call("del", KEYS[1]) end
76	return redis.call("pexpire", KEYS[1], tonumber(ARGV[2]))
77	`;
78	
79	/**
80	 * Gives back the unused tail of a hold: the lock expires `remainingMs` from
81	 * now instead of whenever it was originally due, or is dropped outright when
82	 * that is already zero.
83	 *
84	 * Callers reserve for the worst case (two MusicBrainz calls) because they
85	 * cannot know the shape of a lookup before making it. Most lookups turn out
86	 * cheaper than that, and without this they would leave the upstream idle for
87	 * the difference. `remainingMs` is the airtime the calls actually made still
88	 * owe — never simply zero, or a lookup that finished in 300ms would let the
89	 * next one start immediately and blow the 1 req/s budget.
90	 *
91	 * Best-effort: a failure here just means the lock runs its original course.
92	 */
93	export async function releaseThrottleAfter(redis, service, token, remainingMs) {
94	  if (!token) return false;
95	  try {
96	    const result = await redis.eval(
97	      SHORTEN_IF_OURS,
98	      [`throttle:${service}`],
99	      [token, String(Math.max(0, Math.round(remainingMs)))],
100	    );
101	    return result === 1;
102	  } catch (err) {
103	    console.warn(`releaseThrottleAfter failed for ${service}:`, err.message);
104	    return false;
105	  }
106	}
107	
108	/**
109	 * How long a denied caller should wait before trying the lock again: the
110	 * lock's actual remaining lifetime.
111	 *
112	 * Answering with a constant (the full hold) systematically overshoots — a
113	 * caller denied halfway through someone else's hold sleeps for another full
114	 * hold, so the lock sits idle for the remainder of the first one. Since the
115	 * client sleeps exactly this long before retrying (useLibraryArtists.js),
116	 * handing back the real TTL is what keeps the upstream saturated instead of
117	 * duty-cycled.
118	 *
119	 * PTTL answers -2 when the key is already gone and -1 when it somehow has no
120	 * expiry; both mean "nothing useful to wait for", so retry immediately and
121	 * let SET NX arbitrate. The fallback covers a PTTL that fails outright.
122	 */
123	export async function getThrottleRetryMs(redis, service, fallbackMs) {
124	  try {
125	    const ttl = await redis.pttl(`throttle:${service}`);
126	    return ttl > 0 ? ttl : 0;
127	  } catch (err) {
128	    console.warn(`getThrottleRetryMs failed for ${service}:`, err.message);
129	    return fallbackMs;
130	  }
131	}
