133	export const METRICS_KEY = "metrics:geocode";
134	export const METRICS_RECENT_KEY = "metrics:geocode:recent";
135	// Enough to cover a full library resolution end to end while staying a
136	// bounded, cheap read in the Upstash console.
137	const METRICS_RECENT_MAX = 500;
