141	 *
142	 *   HGETALL metrics:geocode          -- running totals; average = totalMs/count
143	 *   LRANGE  metrics:geocode:recent 0 -1
144	 *
145	 * Samples carry `at`, so consecutive timestamps give the *cadence* (the thing
146	 * the throttle work is actually trying to improve), not just per-request
147	 * duration. Denials and artist-cache hits only bump counters — they are the
148	 * high-frequency cases and would otherwise crowd real lookups out of the
149	 * capped sample list.
150	 *
151	 * Everything runs in one pipelined round-trip, and failures are swallowed:
152	 * measurement must never be able to fail a request.
153	 */
154	export async function recordLookupMetrics(redis, { counters, sample } = {}) {
155	  try {
156	    const pipeline = redis.pipeline();
157	    for (const [field, amount] of Object.entries(counters ?? {})) {
158	      if (amount) pipeline.hincrby(METRICS_KEY, field, amount);
