162	      pipeline.ltrim(METRICS_RECENT_KEY, 0, METRICS_RECENT_MAX - 1);
163	    }
164	    await pipeline.exec();
165	  } catch (err) {
166	    console.warn("recordLookupMetrics failed:", err.message);
167	  }
168	}

