    expect(redis.set).toHaveBeenLastCalledWith(
      "geo:artist-1",
      expect.objectContaining({ status: "resolved", ...location }),
      { ex: 15552000 }, // resolved entries carry a 180-day TTL (see server/kv.js)
    );
  });
});

