1	import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
2	import { sealSession } from "../../server/auth.js";
3	import { geocodeHandler } from "../geocode.js";
4	
5	const DAY_MS = 24 * 60 * 60 * 1000;
6	
7	function mockRes() {
8	  return {
9	    statusCode: 200,
10	    body: undefined,
11	    status(code) {
12	      this.statusCode = code;
13	      return this;
14	    },
15	    json(payload) {
16	      this.body = payload;
17	      return this;
18	    },
19	  };
20	}
