22	// Defaults to a real, validly-sealed session cookie so every test below is
23	// exercising the actual crypto path, not a stand-in. Individual tests that
24	// care about the auth guard itself override `cookie`.
25	function mockReq({
26	  method = "POST",
27	  cookie = `rt=${sealSession("refresh-abc")}`,
28	  body,
29	} = {}) {
30	  const headers = {};
31	  if (cookie) headers.cookie = cookie;
32	  return { method, headers, body };
33	}
34	
35	// Every geocode path now touches Redis for metrics (a pipeline) and may hand
36	// back the tail of its lock (an eval). Tests build their redis from this so a
