import("./server/kv.js").then(async ({ createRedisClient }) => {
  const r = createRedisClient();
  const hash = await r.hgetall("metrics:geocode");
  const raw = await r.lrange("metrics:geocode:recent", 0, -1);
  const s = raw.map((x) => (typeof x === "string" ? JSON.parse(x) : x)).sort((a, b) => a.at - b.at);

  const pct = (arr, p) => arr.slice().sort((a, b) => a - b)[Math.floor((arr.length - 1) * p)];
  const stats = (label, arr) =>
    console.log(`${label.padEnd(22)} n=${String(arr.length).padStart(4)}  avg=${Math.round(arr.reduce((a,b)=>a+b,0)/arr.length).toString().padStart(5)}  p50=${String(pct(arr,0.5)).padStart(5)}  p90=${String(pct(arr,0.9)).padStart(5)}  max=${String(Math.max(...arr)).padStart(6)}`);

  console.log("=== counters ===");
  console.log(hash);
  const avgFromHash = Number(hash.totalMs) / Number(hash.count);
  console.log(`avg duration (hash) = ${avgFromHash.toFixed(0)}ms over ${hash.count} lookups`);
  console.log(`musicBrainzCalls/count = ${(Number(hash.musicBrainzCalls)/Number(hash.count)).toFixed(2)}`);

  console.log("\n=== sample list ===");
  console.log(`${s.length} samples, ${new Date(s[0].at).toISOString()} -> ${new Date(s.at(-1).at).toISOString()}`);
  stats("duration (ms)", s.map((x) => x.ms));

  // Cadence = gap between consecutive lookups, within a run (ignore idle gaps)
  const gaps = [];
  for (let i = 1; i < s.length; i++) {
    const d = s[i].at - s[i - 1].at;
    if (d < 60000) gaps.push(d);
  }
  stats("cadence (ms)", gaps);

  const one = s.filter((x) => x.musicBrainzCalls === 1);
  const two = s.filter((x) => x.musicBrainzCalls === 2);
  console.log(`\n1 MB call: ${one.length}  |  2 MB calls: ${two.length}  -> ${(one.length/s.length*100).toFixed(0)}% single-call`);
  if (one.length) stats("  cadence after 1-call", (() => { const g=[]; for(let i=1;i<s.length;i++){const d=s[i].at-s[i-1].at; if(d<60000 && s[i-1].musicBrainzCalls===1) g.push(d);} return g; })());
  if (two.length) stats("  cadence after 2-call", (() => { const g=[]; for(let i=1;i<s.length;i++){const d=s[i].at-s[i-1].at; if(d<60000 && s[i-1].musicBrainzCalls===2) g.push(d);} return g; })());

  const byOutcome = {};
  for (const x of s) byOutcome[x.outcome] = (byOutcome[x.outcome] ?? 0) + 1;
  console.log("\noutcomes:", byOutcome);
});'

