import("./server/kv.js").then(async ({ createRedisClient }) => {
  const r = createRedisClient();
  const raw = await r.lrange("metrics:geocode:recent", 0, -1);
  const s = raw.map((x) => (typeof x === "string" ? JSON.parse(x) : x)).sort((a, b) => a.at - b.at);

  // Split into runs: a gap over 60s means the loop was idle, not slow.
  const runs = [[s[0]]];
  for (let i = 1; i < s.length; i++) {
    if (s[i].at - s[i-1].at > 60000) runs.push([]);
    runs.at(-1).push(s[i]);
  }
  const med = (a) => a.slice().sort((x,y)=>x-y)[Math.floor((a.length-1)/2)];
  const MERGED = Date.parse("2026-08-09T12:31:15Z");

  for (const run of runs) {
    if (run.length < 5) continue;
    const gaps = []; for (let i=1;i<run.length;i++) gaps.push(run[i].at - run[i-1].at);
    const dur = run.map((x) => x.ms);
    const one = run.filter((x) => x.musicBrainzCalls === 1).length;
    console.log(
      `${new Date(run[0].at).toISOString().slice(5,16)}  ${run.at(-1).at > MERGED ? "PROD (post-merge)" : "pre-merge       "}` +
      `  n=${String(run.length).padStart(3)}` +
      `  cadence p50=${String(med(gaps)).padStart(5)}ms` +
      `  duration p50=${String(med(dur)).padStart(5)}ms` +
      `  1-call=${Math.round(one/run.length*100)}%`,
    );
  }

  const prod = s.filter((x) => x.at > MERGED);
  if (prod.length) {
